                        except (OverflowError, ValueError) as exc:
                            raise FloatingPointError(
                                "non-finite value encountered during gradient "
                                "boosting"
                            ) from exc
                        if not _is_finite_or_int(term):
                            raise FloatingPointError(
                                "non-finite value encountered during gradient "
                                "boosting"
                            )
                        terms.append(term)
